SELECT SUM(v.current_stock) AS current_stock, SUM(v.stock_value) AS stock_value
FROM agent_v3_product_inventory_view AS v
WHERE v.store_id = ANY(:allowedStoreIds) AND (v.current_stock < v.safety_stock) LIMIT 1;

SELECT project_id, project_name, price, duration
FROM agent_v3_project_catalog_view
WHERE agent_v3_project_catalog_view.store_id = ANY(:allowedStoreIds) AND (project_id = 85) LIMIT 100;

SELECT COUNT(DISTINCT reservation_id) AS reservation_count
FROM agent_v3_reservation_view
WHERE agent_v3_reservation_view.store_id = ANY(:allowedStoreIds) AND agent_v3_reservation_view.date >= :startAt AND agent_v3_reservation_view.date < :endAt AND (start_time = '***') LIMIT 1;
